        emon.Port.Cells inks = emon.Port.NewCells();
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Cells sv = emon.Port.NewCells();
        emon.Port.Cells aux = emon.Port.NewCells();
