        RttWord(owords, feats, 1300, y0, 1700, y0 + 100, c3, l);
        Evidence.OlNew(olines, 1, 100, y0, 1700, y0 + 100, 100, y0 + 100, 1700, y0 + 100, 0, 0, first, 3);
